-- Actualiza los procedimientos de JD Cladding Solutions (RUT 78.278.332-7)
-- con el contenido real de sus propios documentos controlados (PTS de
-- Herramientas Eléctricas y Manuales, PR-14 TMERT-MMC, PR-16 PREXOR),
-- reemplazando el texto genérico por el oficial de la empresa. Agrega
-- además el Procedimiento de Accidentes Laborales (PR-09), que no existía
-- como capacitación.

UPDATE erp.procedimientos_capacitacion SET
  objetivo_general = 'Procedimiento de Trabajo Seguro - Uso de Herramientas Eléctricas (esmeril angular y rotomartillo), según documento interno de JD Cladding Solutions SpA.',
  objetivos_especificos = E'Capacitar sobre los siguientes temas:\n• Marco legal: Ley N°16.744 (Art. 184 CT) y D.S. N°594.\n• Alcance: aplica a todo el personal de JD Cladding Solutions SpA involucrado en el control u operación de esmeriles angulares y rotomartillos.\n• Esmeril angular: riesgos del disco (rotura, proyección de partículas, uso de disco incorrecto), riesgos del operador (quemaduras, cortes, contacto eléctrico) y riesgos de la operación (proyección de partículas, incendio por chispas).\n• Medidas con el esmeril: comprobar el disco antes de usar, desconectar la alimentación eléctrica al cambiar el disco, sujetar el equipo con ambas manos, mantener la protección siempre puesta, contar con extintor disponible durante el trabajo.\n• Rotomartillo: riesgos de descargas eléctricas, caídas, cortes, vibración mano-brazo (síndrome del dedo blanco) y exposición a ruido.\n• Medidas con el rotomartillo: sostener la herramienta por la superficie aislada, mantener las ranuras de ventilación descubiertas, esperar a que la herramienta se detenga por completo antes de cambiar accesorios, usar protección auditiva sobre 95 dB.\n• EPP obligatorio: ropa ajustada, zapatos con punta de fierro, casco, lentes y protector facial, protector auditivo, guantes anticorte, coleto de cuero (esmeril) o mascarilla filtro partículas (rotomartillo).\n• Responsabilidades del supervisor, representante de prevención de riesgos y trabajador.'
WHERE codigo = '22' AND empresa_rut_filtro = '78.278.332-7';

UPDATE erp.procedimientos_capacitacion SET
  objetivo_general = 'Procedimiento de Trabajo Seguro - Herramientas Manuales, según documento interno de JD Cladding Solutions SpA.',
  objetivos_especificos = E'Capacitar sobre los siguientes temas:\n• Marco legal: Ley N°16.744 (Art. 184 CT) y D.S. N°594.\n• Alcance: aplica a todo el personal de JD Cladding Solutions SpA.\n• Tipos de herramientas manuales: de golpe (martillos, cinceles), de bordes filosos (cuchillos, hachas), de corte (tenazas, alicates) y de torsión (destornilladores, llaves).\n• Requisitos generales: prohibido usar herramientas defectuosas, dañadas o hechizas; revisión previa por el trabajador; herramientas de golpe sin rebarbas y con empuñadura de seguridad; prohibido modificar herramientas.\n• Almacenamiento: en cajas, paneles o estantes; nunca en pasillos ni expuestas a la intemperie.\n• Mantenimiento: revisión periódica de mangos y recubrimientos aislantes; reparación o baja inmediata ante daño; prohibidas las reparaciones provisorias.\n• Transporte: en cajas, bolsas o cinturones porta herramientas; nunca en los bolsillos; uso de portaherramientas al subir o bajar escaleras para mantener los 3 puntos de apoyo.\n• Peligros y riesgo estimado: moderado; fuentes subestándar (herramienta en mal estado, ruido, falta de iluminación u orden) y actos subestándar (uso indebido, sobreesfuerzo, manipular sin EPP).\n• Medidas de control: usar solo para su función, operar en dirección opuesta al cuerpo, revisar antes de usar, usar fundas para partes filosas, aplicar solo la fuerza necesaria.\n• Responsabilidades de gerencia, supervisor, representante de prevención de riesgos y trabajadores.'
WHERE codigo = '23' AND empresa_rut_filtro = '78.278.332-7';

UPDATE erp.procedimientos_capacitacion SET
  objetivo_general = 'Procedimiento Preventivo TMERT-MMC (PR-14) - Gestión de Riesgos Musculoesqueléticos y Manejo Manual de Cargas, según documento interno de JD Cladding Solutions SpA.',
  objetivos_especificos = E'Capacitar sobre los siguientes temas:\n• Marco normativo: Ley N°16.744, Código del Trabajo Art. 184, D.S. N°44/2024 (gestión preventiva), D.S. N°594/1999, Protocolo de Vigilancia Ocupacional TMERT versión 3 (Res. Ex. MINSAL N°1.697, feb. 2026), Ley N°20.001 y Guía Técnica MMC vigente.\n• Alcance: fachadas metálicas, revestimientos, cielos falsos, baffles, paneles y cubiertas; incluye preparación, traslado, perforación, corte y fijación.\n• Identificación de peligros por actividad: descarga y acopio de perfiles (levantamiento, giro de tronco), fijación sobre cabeza de baffles/cielos (hombros elevados, esfuerzo estático), perforación/atornillado/corte (vibración mano-brazo), trabajo en fachada y techumbre (posturas forzadas, apoyo inestable).\n• Metodología: identificación por tarea, evaluación con las herramientas oficiales del protocolo vigente, intervención priorizada (carros, elevadores de paneles, mesas de apoyo), vigilancia de salud coordinada con el organismo administrador, reevaluación ante cambios de panel, método o equipo.\n• Criterios de suspensión: detener el manejo manual cuando peso, volumen, agarre, postura o condiciones del entorno impidan una operación controlada.\n• Se articula con la matriz IPER/MIPER, los PTS de trabajo en altura, herramientas eléctricas/manuales, instalación de revestimientos, el Procedimiento de Accidentes Laborales y la difusión Ley Karin.\n• Responsabilidades de gerencia, supervisión de obra, trabajadores y organismo administrador.'
WHERE codigo = '21' AND empresa_rut_filtro = '78.278.332-7';

UPDATE erp.procedimientos_capacitacion SET
  objetivo_general = 'Procedimiento Preventivo PREXOR (PR-16) - Prevención de Exposición Ocupacional a Ruido, según documento interno de JD Cladding Solutions SpA.',
  objetivos_especificos = E'Capacitar sobre los siguientes temas:\n• Marco normativo: Ley N°16.744, Código del Trabajo Art. 184, D.S. N°44/2024, D.S. N°594/1999, Protocolo PREXOR del MINSAL, Protocolo ISP para evaluación de exposición a ruido (2025) y Guía ISP de gestión preventiva del ruido (2026).\n• Alcance: obras de fachadas metálicas, revestimientos, cielos falsos, baffles, paneles y cubiertas.\n• Identificación de peligros por actividad: corte de perfiles (ruido continuo de esmeril/sierra), perforación en hormigón o metal (ruido impulsivo), trabajos simultáneos en recintos cerrados (acumulación de fuentes).\n• Jerarquía de control: eliminar o sustituir equipos ruidosos, mantener rodamientos/discos/brocas, encapsular o aislar, planificar secuencias y limitar concurrencia; el protector auditivo es la última barrera.\n• Protección auditiva: seleccionar según datos de exposición y atenuación, verificar compatibilidad con casco y comunicaciones de seguridad.\n• Vigilancia: cuando el protocolo determine exposición, coordinar vigilancia audiométrica con el organismo administrador.\n• Criterios de suspensión: detener tareas si el ruido impide percibir alarmas o señales críticas sin comunicación alternativa segura.\n• Responsabilidades de gerencia, supervisión de obra, trabajadores y organismo administrador.'
WHERE codigo = '19' AND empresa_rut_filtro = '78.278.332-7';

-- Nuevo: Procedimiento de Accidentes Laborales (PR-09), no existía como capacitación
INSERT INTO erp.procedimientos_capacitacion
  (codigo, nombre, objetivo_general, objetivos_especificos, activo, empresa_rut_filtro)
VALUES (
  '25', 'Difusión Procedimiento de Accidentes Laborales',
  'Procedimiento de Accidentes Laborales (PR-09), según documento interno de JD Cladding Solutions SpA.',
  E'Capacitar sobre los siguientes temas:\n• Marco legal: Ley N°16.744 sobre accidentes del trabajo y enfermedades profesionales.\n• Objetivo: respuesta inmediata, atención, denuncia, investigación y seguimiento de accidentes del trabajo y de trayecto, incidentes peligrosos y enfermedades profesionales sospechadas.\n• Respuesta inmediata: detener la faena y controlar peligros sin exponer a rescatistas; alertar al supervisor y servicios de emergencia; primeros auxilios solo por personal capacitado; no mover al lesionado salvo peligro inminente; resguardar la escena y testigos.\n• Denuncia: emitir la DIAT al organismo administrador dentro de las 24 horas de conocido el accidente; ante accidente grave o fatal, suspender la faena afectada e informar de inmediato a la Inspección del Trabajo y a la SEREMI de Salud.\n• Investigación: recopilar testimonios, fotografías, registros de inducción, EPP y permisos; determinar causas inmediatas y básicas sin atribuir culpa automáticamente; definir medidas con responsable, plazo y verificación de eficacia.\n• Responsabilidades: Gerencia (recursos y comunicación de eventos graves), Supervisión (activar respuesta, aislar área), Trabajadores (informar de inmediato), Encargado SST (investigar y registrar), Organismo administrador Ley 16.744 (prestaciones y asistencia técnica).',
  true, '78.278.332-7'
) ON CONFLICT DO NOTHING;
